WITH target AS (SELECT to_regprocedure('public.sales_debt_reconciliation_report_v1(uuid,date,date)') AS fn) SELECT 'sales_debt_reconciliation_report_v1_not_ready' AS problem,fn::text AS function_name,CASE WHEN fn IS NULL THEN 'missing_function' WHEN COALESCE(has_function_privilege('anon',fn,'EXECUTE'),false) THEN 'anon_can_execute' WHEN NOT COALESCE(has_function_privilege('authenticated',fn,'EXECUTE'),false) THEN 'authenticated_cannot_execute' ELSE 'unknown' END AS detail FROM target WHERE fn IS NULL OR COALESCE(has_function_privilege('anon',fn,'EXECUTE'),false) OR NOT COALESCE(has_function_privilege('authenticated',fn,'EXECUTE'),false);
